package gen

// Comparison against outputs of the original D implementation.
//
// Needs a directory of reference outputs, generated by a D build patched to
// seed its random generator and dump the generated points to <name>.points
// (one "%a %a" line per point). For each <name>.json in the directory, the
// test runs the Go pipeline on the same points, from the directory, and
// compares elevations (via <name>.json.obj) and the heightmap
// (<name>.json.png).
//
//	WGEN_DREF=/path/to/refs go test ./internal/gen -run DReference -v

import (
	"bufio"
	"fmt"
	"image"
	"image/png"
	"math"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
	"testing"

	"github.com/Castux/wgen/internal/config"
	"github.com/Castux/wgen/internal/geom"
)

func TestDReference(t *testing.T) {
	dir := os.Getenv("WGEN_DREF")
	if dir == "" {
		t.Skip("WGEN_DREF not set")
	}

	configs, _ := filepath.Glob(filepath.Join(dir, "*.json"))
	if len(configs) == 0 {
		t.Fatal("no reference configs found")
	}

	t.Chdir(dir)

	for _, path := range configs {
		name := strings.TrimSuffix(filepath.Base(path), ".json")
		t.Run(name, func(t *testing.T) { compareDReference(t, name) })
	}
}

func compareDReference(t *testing.T, name string) {
	points := readPoints(t, name+".points")
	pointsHook = func(*World) []geom.Vec2 { return points }
	defer func() { pointsHook = nil }()

	conf, _, err := config.Load(name + ".json")
	if err != nil {
		t.Fatal(err)
	}

	w, err := New(conf)
	if err != nil {
		t.Fatal(err)
	}

	// Elevation per vertex, matched by position

	ref := readOBJElevations(t, name+".json.obj")
	if len(ref) != len(w.Mesh.Points) {
		t.Errorf("vertex count: D %d, Go %d", len(ref), len(w.Mesh.Points))
	}

	var missing, differ int
	var maxDiff, sumDiff float64
	for v, p := range w.Mesh.Points {
		refZ, ok := ref[posKey(p.X, -p.Y)]
		if !ok {
			missing++
			continue
		}

		z := w.Z[v]
		if math.IsNaN(z) {
			z = 0
		}
		if math.IsNaN(refZ) {
			refZ = 0
		}

		d := math.Abs(z - refZ)
		sumDiff += d
		maxDiff = math.Max(maxDiff, d)
		if d > 1e-5 {
			differ++
		}
	}

	t.Logf("vertices: %d, unmatched %d, differing elevation %d (%.3f%%), max diff %.4g, mean diff %.4g, range %.4g..%.4g",
		len(w.Mesh.Points), missing, differ, 100*float64(differ)/float64(len(w.Mesh.Points)),
		maxDiff, sumDiff/float64(len(w.Mesh.Points)), w.Lowest, w.Highest)

	if missing > 0 {
		t.Errorf("%d vertices not found in the reference", missing)
	}

	// Heightmap pixels

	img := readPNG(t, name+".json.png")
	var pixelsDiffer int
	var maxPixelDiff float64

	for y := range w.Height {
		for x := range w.Width {
			v := w.Heightmap[y*w.Width+x]
			if math.IsNaN(v) {
				v = 0
			}
			v = geom.Clamp(math.Floor(v), 0, 65535)

			refV := float64(img.Gray16At(x, w.Height-1-y).Y)
			if !w.Conf.PNG16 {
				refV = float64(img.Gray16At(x, w.Height-1-y).Y >> 8)
			}

			if d := math.Abs(v - refV); d > 0 {
				pixelsDiffer++
				maxPixelDiff = math.Max(maxPixelDiff, d)
			}
		}
	}

	t.Logf("heightmap: %d pixels, %d differ (%.3f%%), max diff %g",
		w.Width*w.Height, pixelsDiffer, 100*float64(pixelsDiffer)/float64(w.Width*w.Height), maxPixelDiff)

	// Exported faces (skipping those outside the map)

	refFaces := readOBJFaces(t, name+".json.obj")
	faces, same := 0, 0
	for _, tri := range w.Mesh.Triangles {
		if w.Terrain[tri[0]] == nil || w.Terrain[tri[1]] == nil || w.Terrain[tri[2]] == nil {
			continue
		}
		faces++
		var keys []string
		for _, v := range tri {
			keys = append(keys, posKey(w.Mesh.Points[v].X, -w.Mesh.Points[v].Y))
		}
		slices.Sort(keys)
		if refFaces[strings.Join(keys, "|")] {
			same++
		}
	}
	t.Logf("faces: D %d, Go %d, in common %d", len(refFaces), faces, same)
	if faces != len(refFaces) || same != faces {
		t.Errorf("exported faces differ")
	}

	// Rivers

	rivers := 0
	for _, d := range w.Downhill {
		if d >= 0 {
			rivers++
		}
	}
	refRivers := countLines(t, name+".json.svg", "<line")
	t.Logf("river segments: D %d, Go %d", refRivers, rivers)
}

func readOBJFaces(t *testing.T, path string) map[string]bool {
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}

	var vertices []string
	faces := map[string]bool{}
	for _, line := range strings.Split(string(data), "\n") {
		fields := strings.Fields(line)
		switch {
		case len(fields) == 4 && fields[0] == "v":
			x, _ := strconv.ParseFloat(fields[1], 64)
			y, _ := strconv.ParseFloat(fields[3], 64)
			vertices = append(vertices, posKey(x, y))
		case len(fields) == 4 && fields[0] == "f":
			var keys []string
			for _, f := range fields[1:] {
				i, _ := strconv.Atoi(strings.Split(f, "/")[0])
				keys = append(keys, vertices[i-1])
			}
			slices.Sort(keys)
			faces[strings.Join(keys, "|")] = true
		}
	}
	return faces
}

func countLines(t *testing.T, path, prefix string) int {
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	n := 0
	for _, line := range strings.Split(string(data), "\n") {
		if strings.HasPrefix(line, prefix) {
			n++
		}
	}
	return n
}

func posKey(x, y float64) string { return fmt.Sprintf("%.6f %.6f", x, y) }

func readPoints(t *testing.T, path string) []geom.Vec2 {
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	var points []geom.Vec2
	s := bufio.NewScanner(f)
	for s.Scan() {
		fields := strings.Fields(s.Text())
		x, err1 := strconv.ParseFloat(fields[0], 64)
		y, err2 := strconv.ParseFloat(fields[1], 64)
		if err1 != nil || err2 != nil {
			t.Fatalf("bad point line %q", s.Text())
		}
		points = append(points, geom.Vec2{X: x, Y: y})
	}
	return points
}

// readOBJElevations maps "x -y" to z from the "v x z -y" lines.
func readOBJElevations(t *testing.T, path string) map[string]float64 {
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	res := map[string]float64{}
	s := bufio.NewScanner(f)
	for s.Scan() {
		line := s.Text()
		if !strings.HasPrefix(line, "v ") {
			continue
		}
		var x, y, z float64
		fmt.Sscanf(line, "v %f %f %f", &x, &z, &y)
		res[posKey(x, y)] = z
	}
	return res
}

func readPNG(t *testing.T, path string) *image.Gray16 {
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	img, err := png.Decode(f)
	if err != nil {
		t.Fatal(err)
	}

	b := img.Bounds()
	g := image.NewGray16(b)
	for y := b.Min.Y; y < b.Max.Y; y++ {
		for x := b.Min.X; x < b.Max.X; x++ {
			g.Set(x, y, img.At(x, y))
		}
	}
	return g
}
